{
  "window_id": "w0010",
  "observed_failures": [
    {
      "id": "F1",
      "summary": "Binary task reward is 0.0 despite 40/44 field accuracy; 4 field errors cause oracle line-by-line diff to fail.",
      "evidence": "execution_metadata.original_reward=0.0, feedback.reward=0.909 (40/44 fields), delivery_status=valid."
    },
    {
      "id": "F2",
      "summary": "Empty string '' written for 078.jpg total_amount where task requires null.",
      "evidence": "predictions row for 078.jpg has total_amount='' ; task spec: 'If extraction fails ... value is set to null'; feedback flags amount_correct=false for 078."
    },
    {
      "id": "F3",
      "summary": "074.jpg total predicted 702.00 instead of 102.00 — OCR digit confusion on the TOTAL line ('Totalincl. of GBT 702.00' in raw OCR vs visible '102.00').",
      "evidence": "Window shows OCR of 074: 'Totalincl. of GBT 702.00'; image clearly reads 102.00. Single-pass OCR with no preprocessing/variant voting."
    },
    {
      "id": "F4",
      "summary": "077.jpg total predicted 23.26 instead of final rounded TOTAL 23.25. Extractor accepted the 'Total (Inclusive of GST): 23.26' line even though the final 'TOTAL: 23.25' line appears later after a Rounding Adj.",
      "evidence": "Image shows 'Total (Inclusive of GST): 23.26 / Rounding Adj: -0.01 / TOTAL: 23.25'. First-match-wins in the TOTAL tier picks 23.26 and never consults the final line."
    },
    {
      "id": "F5",
      "summary": "034.jpg date predicted 2018-08-09 instead of 2018-03-09 — digit '3' read as '8' by Tesseract in 'Date: 09/08/2018' OCR vs visible '09/03/2018'.",
      "evidence": "Window shows 034 OCR line 'Date: 09/08/2018'; image shows '09/03/2018'. Only one OCR pass used; no agreement/voting across preprocessing variants."
    },
    {
      "id": "F6",
      "summary": "Agent exhausted its iteration budget (65/65, termination_reason=max_iterations), suggesting the workflow is not minimal — a lot of per-image exploratory OCR instead of one deterministic pipeline.",
      "evidence": "execution_metadata.agent_iterations=65, max_iterations_at_source=65, stop_reason=max_iterations; response_tool_call_counts show 27 terminal + 22 think + 16 file_editor calls."
    },
    {
      "id": "F7",
      "summary": "n_skill_invocations=0 — the agent never explicitly consulted the preloaded SKILL docs, so any refinements only help if the Skill content becomes self-sufficient guidance that the agent internalizes at preload time.",
      "evidence": "execution_metadata.n_skill_invocations=0; skill_exposure_mode=persistent-agent-context-full-skill-md."
    }
  ],
  "root_causes": [
    {
      "id": "R1",
      "summary": "Original image-ocr Skill has no receipt-field extraction contract. It teaches raw OCR + a JSON schema with 'extracted_text/confidence/warnings', but gives no priority/exclusion keyword logic, no two-line fallback, no amount-string formatting, and no date ISO normalization.",
      "related_failures": ["F2","F3","F4","F5"]
    },
    {
      "id": "R2",
      "summary": "Original xlsx Skill is written for financial models, not strict-schema graders. It actively pushes formulas and formatting, and never warns about null vs '' vs NaN, column/sheet name exactness, dtype preservation ('47.70' as str not float), or row ordering by filename.",
      "related_failures": ["F1","F2"]
    },
    {
      "id": "R3",
      "summary": "No guidance to perform multi-pass OCR with voting/agreement across preprocessing variants and PSM modes for high-stakes numeric fields, so single-pass digit confusions (3↔8, 1↔7, O↔0) propagate directly into the output.",
      "related_failures": ["F3","F5"]
    },
    {
      "id": "R4",
      "summary": "Keyword matching logic implied by the hint is under-specified: exclusion keywords must be substring-checked against the whole line (so 'Total (Inclusive of GST)' is dropped via 'GST'), and when multiple lines match the same priority tier the later 'rounded/final' line should win over an earlier gross/incl-GST line.",
      "related_failures": ["F4"]
    },
    {
      "id": "R5",
      "summary": "No explicit instruction that failed extractions must materialize as real Excel nulls (Python None) via an object dtype — leading the agent to write '' and still consider delivery valid.",
      "related_failures": ["F2"]
    },
    {
      "id": "R6",
      "summary": "No minimal end-to-end pipeline template in the Skills, so the agent re-derives the pipeline interactively per image, burning iterations.",
      "related_failures": ["F6","F7"]
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defect": "Missing: priority-tiered keyword matching, exclusion-keyword substring filter (including GST/SST/TAX against any part of the line), two-line fallback, preference for later/rounded match within a priority tier, numeric normalization to 'N.NN' string, ISO date normalization with explicit DD/MM/YYYY precedence for Malaysian receipts, and per-image try/except returning None fields."
    },
    {
      "skill": "image-ocr",
      "defect": "Missing: multi-pass OCR *with voting/agreement* for date and total (not just concatenating all text), and digit-focused preprocessing variants (grayscale+autocontrast, 2x upscale, binarization at multiple thresholds, PSM 6/4/11) tried until two independent passes agree on the value."
    },
    {
      "skill": "image-ocr",
      "defect": "Missing: fuzzy/robust keyword detection to survive OCR garbling of the keyword itself (e.g., 'GrandTota', 'Tolal', 'TOTAI'), using regex like r'G\\s*R\\s*A\\s*N\\s*D[\\s_]*T[0O]TA[LI]' or small edit-distance match before falling back to the generic TOTAL tier."
    },
    {
      "skill": "xlsx",
      "defect": "Missing strict-schema output contract: exact sheet name, exact column order and headers, index=False, no extra sheets/columns, lexicographic filename sort, and dtype='object' so strings like '47.70' survive and None cells render as real blanks (not NaN, not '')."
    },
    {
      "skill": "xlsx",
      "defect": "Missing anti-pattern list specific to graders: never use float for monetary strings, never write '' or 'None' for null, never auto-create Sheet1, never add index column, never keep currency/comma formatting in the value."
    },
    {
      "skill": "xlsx",
      "defect": "No verification step: after writing, re-open the file and assert sheet names, column names, row order, and that non-null totals match /^\\d+\\.\\d{2}$/ and nulls are truly null."
    },
    {
      "skill": "image-ocr",
      "defect": "No canonical, minimal end-to-end pipeline (iter sorted images → per-image try/except → date+total extractors → rows list) so the agent must reinvent it and consumes iterations."
    }
  ],
  "repair_recommendations": [
    {
      "target": "skills/image-ocr/SKILL.md",
      "change": "Add a 'Structured Field Extraction (Receipts/Forms)' section defining: (a) ordered keyword priority tiers (GRAND TOTAL → TOTAL RM/TOTAL: RM → TOTAL AMOUNT → NETT?/NET TOTAL, TOTAL DUE, AMOUNT DUE, BALANCE DUE, TOTAL, AMOUNT); (b) EXCLUSION list checked as case-insensitive substring over the full line (SUBTOTAL, SUB TOTAL, TAX, GST, SST, DISCOUNT, CHANGE, CASH TENDERED); (c) two-line fallback using last number on the next non-empty line; (d) within the same priority tier, if multiple lines match, prefer the LAST match whose line also contains 'ROUND', 'NET', or 'FINAL', else the last match; (e) strip currency/commas; (f) format as f'{v:.2f}' string, else None."
    },
    {
      "target": "skills/image-ocr/SKILL.md",
      "change": "Add a 'Robust-OCR for Numeric Fields' subsection: run OCR with at least 3 preprocessing variants (autocontrast grayscale, 2x upscale + sharpen, Otsu-like threshold) × PSM {6,4,11}; apply extract_total to each pass; vote and accept the value only if ≥2 passes agree; otherwise fall back to the highest-priority consistent value. Same for extract_date (vote on ISO result, not raw string)."
    },
    {
      "target": "skills/image-ocr/SKILL.md",
      "change": "Add fuzzy keyword detection: regex variants tolerant of OCR noise (e.g., r'G\\W*R\\W*A\\W*N\\W*D\\W*T[O0]\\W*T\\W*A\\W*[LI1]' for GRAND TOTAL; r'T[O0]\\W*T\\W*A\\W*[LI1]\\W*R?\\W*[MN]' for TOTAL RM) before the strict tiered search, and only attach the fuzzy match to its priority tier if the line is NOT excluded."
    },
    {
      "target": "skills/image-ocr/SKILL.md",
      "change": "Add ISO date extraction with explicit format precedence for receipt locales (DD/MM/YYYY, DD-MM-YYYY, DD/MM/YY, DD MMM YYYY, DD-MMM-YYYY, YYYY-MM-DD, YYYY/MM/DD); try both DD/MM and MM/DD interpretations only when the first fails validity; always return 'YYYY-MM-DD' or None."
    },
    {
      "target": "skills/image-ocr/SKILL.md",
      "change": "Add a 'Null-Safe Per-Image Pipeline' snippet: process_receipt() must wrap OCR + extractors in try/except and return {'date': None, 'total_amount': None} on any failure. Never return '', 'None', 'nan'."
    },
    {
      "target": "skills/image-ocr/SKILL.md",
      "change": "Add a 'Deterministic Batch Ordering' note: sort inputs lexicographically by filename via sorted(Path(dir).iterdir(), key=lambda p: p.name), filter to {.jpg,.jpeg,.png,.webp}, skip hidden files."
    },
    {
      "target": "skills/xlsx/SKILL.md",
      "change": "Add a top-level 'Strict-Schema Outputs (graded line-by-line)' section with a checklist: exact file path; exactly one sheet with the exact name; exact column order and header text; index=False; no extra columns/sheets; row count equals input count; lexicographic filename ordering; numeric-looking fields that must be strings written as str (e.g., '47.70'), not float; missing values as Python None producing empty cells (never '', 'None', 'NaN')."
    },
    {
      "target": "skills/xlsx/SKILL.md",
      "change": "Add a canonical pandas pattern: build list[dict] in exact column order, construct DataFrame with explicit columns=[...], cast nullable string columns to dtype='object', sort_values('filename', kind='stable'), write via pd.ExcelWriter(engine='openpyxl') with explicit sheet_name."
    },
    {
      "target": "skills/xlsx/SKILL.md",
      "change": "Add a mandatory 'Verify by re-reading' step: pd.read_excel(sheet_name=None); assert keys==[expected]; assert column names and order; assert filename sort; assert every non-null amount matches ^\\d+\\.\\d{2}$ and every null cell is pd.isna == True (not the string 'nan')."
    },
    {
      "target": "skills/xlsx/SKILL.md",
      "change": "Scope the 'CRITICAL: Use Formulas, Not Hardcoded Values' guidance to analytical/financial models and add an explicit note: for strict-schema extraction outputs, every cell must be a literal value matching the oracle — do NOT introduce formulas, totals, or helper columns."
    },
    {
      "target": "skills/image-ocr/SKILL.md and skills/xlsx/SKILL.md",
      "change": "Cross-reference: image-ocr's 'Structured Field Extraction' section should link to xlsx's 'Strict-Schema Outputs' section so the agent sees a single end-to-end recipe (OCR → extract → None-safe rows → strict Excel write → re-read verification)."
    },
    {
      "target": "skills/image-ocr/SKILL.md",
      "change": "Add a 'Common receipt total pitfalls' list with concrete examples to bias extraction: 'Total (Inclusive of GST)' lines are EXCLUDED (contain GST); prefer later 'Total Rounded'/'Net Total'/'TOTAL' within same tier; 'Cash Tendered' is excluded; numbers like '102.00' are frequently misread as '702.00' or '102.0C' — require two independent passes to agree before accepting."
    }
  ],
  "confidence": {
    "observed_failures": "high",
    "root_causes": "high",
    "skill_defects": "high",
    "repair_recommendations": "medium-high",
    "notes": "Diagnosis is grounded in the preserved raw OCR text for each failed receipt and the direct images. Repairs are generalizable (keyword tiers, exclusion substring matching, multi-pass voting, strict-schema contract, null handling) rather than specific to the 22 sample receipts. Remaining uncertainty is mostly around how much OCR-vote robustness a single extra preprocessing pass buys for ambiguous digits (3↔8), which may still require handwritten-case fallbacks."
  }
}
